/* Signature Assistance Services Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Claria": "From clara (clear): assistant name, 'the clear-voiced'.", "Veriton": "From veritas (truth) + -on: assistant name.", "Audela": "From audio + -ela: assistant name.", "Miravox": "From mira (wonder) + vox (voice): 'wonder voice'.", "Solace": "From solace (comfort): assistant name.", "Vigil": "From vigil (watch): assistant name.", "Claria Voice": "Signature brand-product compound.", "Veriton Mind": "Signature brand-product compound.", "Miravox Labs": "Signature brand-product compound.", "Solace Systems": "Signature brand-product compound."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Claria';
console.log(lookup(q));

